"""
Add a second coupling term to the tier-1 (ADC-GW)

matrix. The paper states that, with this term included, the resulting

scheme is exactly equivalent to a self-energy already published by a

different group (GW+2SOSEX made positive semi-definite). This term is

therefore not new physics. It is still a paper-specific formula that

must be implemented correctly: two sums with similar-looking factors

but different energy denominators.

The second-order screened-exchange (SOSEX)

correction adds an exchange-like coupling on top of plain GW. In the

algebraic-diagrammatic construction used here, this appears as an

additional contribution to the coupling between the reference orbital

and every two-hole-one-particle or two-particle-one-hole configuration.

It is built from the same GW effective integrals together with the bare

two-electron integrals.

Returns
-------
the assembled square matrix, same shape as the     tier-1 matrix.
"""

# =============================================================================
# FUNCTION SIGNATURE (shown to the LLM)
# =============================================================================

def adc_2sosex_matrix(
    eps: list[float],
    chem_spatial: dict[tuple[int, int, int, int], float],
    occ: list[int],
    vir: list[int],
    omega: list[float],
    M: list[list[list[float]]],
    probe: int,
) -> list[list[float]]:
    """
    Assemble the tier-2 (ADC-2SOSEX) effective Hamiltonian for one
    probed orbital, by adding a second coupling contribution to the
    tier-1 matrix from the previous step.

    Args:
        eps, occ, vir, omega, M, probe: as in the tier-1 step.
        chem_spatial: bare two-electron Coulomb integrals over the
            active spatial orbitals, as in earlier steps.

    Conventions:
        - The row and column layout is the same as in the tier-1
          matrix.
        - The diagonal entries (the unperturbed configuration energies)
          are unchanged from tier 1.
        - Some terms would require a division by an energy denominator
          that is extremely close to zero (magnitude below 1e-9) while
          every GW effective integral the term multiplies is itself
          negligible (magnitude below 1e-9). Such a term contributes
          exactly 0.0 to the sum. When both parts of this condition
          hold, the term is an exact cancellation, and it must not be
          evaluated as a division.

    """
    return []

# =============================================================================
# GOLD SOLUTION
# =============================================================================

def _oracle_adc_2sosex_matrix(
    eps: list[float],
    chem_spatial: dict[tuple[int, int, int, int], float],
    occ: list[int],
    vir: list[int],
    omega: list[float],
    M: list[list[list[float]]],
    probe: int,
) -> list[list[float]]:
    H = _oracle_adc_gw_tier1_matrix(eps, occ, vir, omega, M, probe)
    nexc = len(omega)

    def _phys(p, q, r, s):
        if p % 2 != r % 2 or q % 2 != s % 2:
            return 0.0
        return chem_spatial.get((p//2, r//2, q//2, s//2), 0.0)

    def _safe_term(m_factor, rest, denom):
        if abs(m_factor) < 1e-9 and abs(denom) < 1e-9:
            return 0.0
        return m_factor*rest/denom

    row = 1
    for j in occ:
        for nu in range(nexc):
            add = 0.0
            for k in occ:
                for c in vir:
                    add += _safe_term(M[c][k][nu], _phys(j, c, k, probe), eps[c]-eps[k]+omega[nu])
                    add += _safe_term(M[k][c][nu], _phys(j, k, c, probe), eps[c]-eps[k]-omega[nu])
            H[0][row] += add
            H[row][0] += add
            row += 1
    for b in vir:
        for nu in range(nexc):
            add = 0.0
            for k in occ:
                for c in vir:
                    add += _safe_term(M[c][k][nu], _phys(b, k, c, probe), eps[c]-eps[k]+omega[nu])
                    add += _safe_term(M[k][c][nu], _phys(b, c, k, probe), eps[c]-eps[k]-omega[nu])
            H[0][row] += add
            H[row][0] += add
            row += 1
    return H

